-- Demo faces for every provider who has no photo yet (the four drawn faces in
-- assets/demo/, handed out in Team-tab order and repeating if there are more
-- than four). Photos added on the Team tab are kept. Safe to run more than once.
with faces(n, photo) as (values
  (0, 'data:image/svg+xml;base64,'),
  (1, 'data:image/svg+xml;base64,'),
  (2, 'data:image/svg+xml;base64,'),
  (3, 'data:image/svg+xml;base64,')
), todo as (
  select id, (row_number() over (order by sort, id) - 1) % 4 as n from public.providers where photo is null
)
update public.providers p set photo = f.photo
from todo t join faces f on f.n = t.n
where p.id = t.id
returning p.name, 'demo face added' as done;
